CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(100) PRIMARY KEY, `value` LONGTEXT NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS discord_members (user_id VARCHAR(24) PRIMARY KEY, username VARCHAR(100) NOT NULL, global_name VARCHAR(100) NULL, avatar TEXT NULL, role_ids LONGTEXT NOT NULL, in_guild TINYINT(1) NOT NULL DEFAULT 0, synced_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS records (id VARCHAR(64) PRIMARY KEY, collection VARCHAR(64) NOT NULL, data LONGTEXT NOT NULL, created_by VARCHAR(24) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_records_collection_created(collection,created_at));
CREATE TABLE IF NOT EXISTS tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ticket_number VARCHAR(24) UNIQUE, owner_id VARCHAR(24) NOT NULL, subject VARCHAR(120) NOT NULL, category VARCHAR(40) NOT NULL DEFAULT 'General', status VARCHAR(20) NOT NULL DEFAULT 'open', claimed_by VARCHAR(24) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, closed_at DATETIME NULL, INDEX idx_ticket_owner(owner_id));
CREATE TABLE IF NOT EXISTS ticket_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ticket_id BIGINT UNSIGNED NOT NULL, author_id VARCHAR(24) NOT NULL, author_name VARCHAR(100) NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL, INDEX idx_ticket_messages(ticket_id));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id VARCHAR(24) NULL, actor_name VARCHAR(100) NULL, action VARCHAR(120) NOT NULL, target_type VARCHAR(100) NULL, target_id VARCHAR(100) NULL, details LONGTEXT NULL, result VARCHAR(20) NOT NULL DEFAULT 'success', ip VARCHAR(64) NULL, created_at DATETIME NOT NULL, INDEX idx_audit_created(created_at));
CREATE TABLE IF NOT EXISTS shifts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id VARCHAR(24) NOT NULL, started_at BIGINT NOT NULL, ended_at BIGINT NULL, duration_seconds BIGINT NULL, start_source VARCHAR(40) NOT NULL DEFAULT 'discord', end_source VARCHAR(40) NULL, created_at DATETIME NOT NULL, INDEX idx_shifts_user_started(user_id,started_at));
CREATE TABLE IF NOT EXISTS clock_adjustments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id VARCHAR(24) NOT NULL, kind VARCHAR(20) NOT NULL, period VARCHAR(20) NOT NULL DEFAULT '', minutes INT NOT NULL DEFAULT 0, reason VARCHAR(300) NOT NULL, actor_id VARCHAR(24) NOT NULL, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS legacy_clock_totals (user_id VARCHAR(24) NOT NULL, kind VARCHAR(20) NOT NULL, period VARCHAR(20) NOT NULL DEFAULT '', minutes BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(user_id,kind,period));
